import {
  Body,
  Container,
  Head as EmailHead,
  Html,
  Preview,
  Section,
  Heading,
  Text,
  Link,
  Column,
  Row,
  Img,
} from "jsx-email";
import { Fragment } from "react";
import type { ReactElement } from "react";

import { DefaultFonts } from "@/components/email/font-default";
import { EmailTailwind } from "@/components/email/email-theme";
import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

type Cta_CTAWithImageStripVariant =
  | "boxed-right"
  | "boxed-left"
  | "full-right"
  | "full-left";

interface Cta_CTAWithImageStripProps {
  theme?: EmailTheme;
  heading?: string;
  subtext?: string;
  ctaLabel?: string;
  ctaHref?: string;
  imageSrc1?: string;
  imageAlt1?: string;
  imageSrc2?: string;
  imageAlt2?: string;
  imageSrc3?: string;
  imageAlt3?: string;
  imageSrc4?: string;
  imageAlt4?: string;
  imageSrc5?: string;
  imageAlt5?: string;
  pageBackgroundColor?: string;
  backgroundColor?: string;
  stripBackgroundColor?: string;
  headingColor?: string;
  textColor?: string;
  buttonBackgroundColor?: string;
  buttonTextColor?: string;
  variant?: Cta_CTAWithImageStripVariant;
}

const Cta_fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const Cta_responsiveStyles = `
    @media only screen and (max-width: 599px) {
      .cta-strip-inner {
        margin-left: auto !important;
        margin-right: auto !important;
        width: auto !important;
      }

      .cta-strip-stack {
        display: block !important;
        width: 100% !important;
      }

      .cta-strip-outer-content {
        padding: 0 !important;
      }

      .cta-strip-copy {
        padding-left: 24px !important;
        padding-right: 24px !important;
        text-align: center !important;
      }

      .cta-strip-gap {
        line-height: 20px !important;
      }
    }

    .cta-strip-button:hover {
      background-color: #4338ca !important;
    }
  `;

const Cta_sharedStripAssets = {
  imageSrc2: emailAsset("cta/strip-2.jpg"),
  imageSrc4: emailAsset("cta/strip-4.jpg"),
  imageSrc5: emailAsset("cta/strip-5.jpg"),
};

const Cta_variantContent = {
  "boxed-left": {
    imageSrc1: emailAsset("cta/strip-cut-1.jpg"),
    imageSrc3: emailAsset("cta/strip-cut-2.jpg"),
    stripBackgroundColor: "#030712",
    ...Cta_sharedStripAssets,
  },
  "boxed-right": {
    imageSrc1: emailAsset("cta/strip-cut-1.jpg"),
    imageSrc3: emailAsset("cta/strip-cut-2.jpg"),
    stripBackgroundColor: "#e5e7eb",
    ...Cta_sharedStripAssets,
  },
  "full-left": {
    imageSrc1: emailAsset("cta/strip-1.jpg"),
    imageSrc3: emailAsset("cta/strip-3.jpg"),
    stripBackgroundColor: "#fffffe",
    ...Cta_sharedStripAssets,
  },
  "full-right": {
    imageSrc1: emailAsset("cta/strip-1.jpg"),
    imageSrc3: emailAsset("cta/strip-3.jpg"),
    stripBackgroundColor: "#fffffe",
    ...Cta_sharedStripAssets,
  },
} satisfies Record<
  Cta_CTAWithImageStripVariant,
  {
    imageSrc1: string;
    imageSrc2: string;
    imageSrc3: string;
    imageSrc4: string;
    imageSrc5: string;
    stripBackgroundColor: string;
  }
>;

const Cta_defaultSectionStyles = {
  backgroundColor: "#fffffe",
  buttonBackgroundColor: "#4f46e5",
  buttonTextColor: "#f8fafc",
  ctaHref: "https://example.com/",
  ctaLabel: "Sign up today",
  heading: "Join the Adventure",
  headingColor: "#030712",
  imageAlt1: "",
  imageAlt2: "",
  imageAlt3: "",
  imageAlt4: "",
  imageAlt5: "",
  pageBackgroundColor: "#f1f5f9",
  subtext:
    "Join a community built for explorers. Sign up today and get early access to new collections, gear guides, and exclusive offers made for the outdoors.",
  textColor: "#4b5563",
};

type Cta_SectionProps = Omit<Cta_CTAWithImageStripProps, "theme">;

type Cta_ResolvedProps = typeof Cta_defaultSectionStyles &
  (typeof Cta_variantContent)[Cta_CTAWithImageStripVariant];

const Cta_CTAContent = ({
  buttonBackgroundColor,
  buttonTextColor,
  ctaHref,
  ctaLabel,
  heading,
  headingColor,
  subtext,
  textColor,
}: Cta_ResolvedProps) => (
  <Section className="cta-strip-copy">
    <Section style={{ lineHeight: "24px" }}>&zwj;</Section>
    <Heading
      style={{
        color: headingColor,
        fontFamily: Cta_fontFamily,
        fontSize: "24px",
        fontWeight: 500,
        lineHeight: "32px",
        margin: 0,
      }}
      as="h2"
    >
      {heading}
    </Heading>
    <Section style={{ lineHeight: "16px" }}>&zwj;</Section>
    <Text
      style={{
        color: textColor,
        fontFamily: Cta_fontFamily,
        fontSize: "16px",
        fontWeight: 300,
        lineHeight: "24px",
        margin: 0,
      }}
    >
      {subtext}
    </Text>
    <Section style={{ lineHeight: "36px" }}>&zwj;</Section>
    <Link
      className="cta-strip-button"
      href={ctaHref}
      style={{
        backgroundColor: buttonBackgroundColor,
        borderRadius: "8px",
        color: buttonTextColor,
        display: "inline-block",
        fontFamily: Cta_fontFamily,
        fontSize: "16px",
        fontWeight: 500,
        lineHeight: "24px",
        padding: "10px 22px",
        textAlign: "center",
        textDecoration: "none",
      }}
    >
      {ctaLabel}
    </Link>
    <Section style={{ lineHeight: "24px" }}>&zwj;</Section>
  </Section>
);

const Cta_StripImage = ({
  alt,
  borderRadius = "4px",
  src,
}: {
  alt: string;
  borderRadius?: string;
  src: string;
}) => (
  <Img
    alt={alt}
    src={src}
    style={{ borderRadius, maxWidth: "100%", verticalAlign: "middle" }}
    width="116"
  />
);

const Cta_ImageColumn = ({
  children,
  firstOffset = false,
}: {
  children: ReactElement<{
    src: string;
  }>[];
  firstOffset?: boolean;
}) => (
  <Column style={{ verticalAlign: "middle" }}>
    {children.map((child, index) => (
      <Section
        key={child.props.src}
        style={{ marginTop: index === 0 && !firstOffset ? 0 : "24px" }}
      >
        {child}
      </Section>
    ))}
  </Column>
);

const Cta_ImageStrip = ({
  boxed,
  left,
  props,
}: {
  boxed: boolean;
  left: boolean;
  props: Cta_ResolvedProps;
}) => (
  <Column
    className="cta-strip-stack"
    style={{
      backgroundColor: props.stripBackgroundColor,
      width: boxed ? "304px" : undefined,
    }}
  >
    <Section className="cta-strip-inner" width="100%">
      <Fragment>
        <Row>
          {boxed || left ? (
            <Column style={{ width: "24px" }}>&zwj;</Column>
          ) : null}
          <Cta_ImageColumn firstOffset={!boxed}>
            <Cta_StripImage
              alt={props.imageAlt1}
              borderRadius={boxed ? "0 0 4px 4px" : "4px"}
              src={props.imageSrc1}
            />
            <Cta_StripImage alt={props.imageAlt2} src={props.imageSrc2} />
            <Cta_StripImage
              alt={props.imageAlt3}
              borderRadius={boxed ? "4px 4px 0 0" : "4px"}
              src={props.imageSrc3}
            />
          </Cta_ImageColumn>
          <Column style={{ width: "24px" }}>&zwj;</Column>
          <Cta_ImageColumn>
            <Cta_StripImage alt={props.imageAlt4} src={props.imageSrc4} />
            <Cta_StripImage alt={props.imageAlt5} src={props.imageSrc5} />
          </Cta_ImageColumn>
          {boxed || !left ? (
            <Column style={{ width: "24px" }}>&zwj;</Column>
          ) : null}
        </Row>
      </Fragment>
    </Section>
  </Column>
);

const Cta_CTAWithImageStripSection = (props: Cta_SectionProps) => {
  const variant = props.variant ?? "boxed-right";
  const resolved = {
    ...Cta_defaultSectionStyles,
    ...Cta_variantContent[variant],
    ...props,
  } as Cta_ResolvedProps;
  const boxed = variant.startsWith("boxed");
  const left = variant.endsWith("left");
  const contentCell = (
    <Column
      className="cta-strip-stack"
      style={{
        textAlign: "left",
        verticalAlign: "middle",
        width: boxed ? "228px" : "252px",
      }}
    >
      <Cta_CTAContent {...resolved} />
    </Column>
  );
  const stripCell = (
    <Cta_ImageStrip boxed={boxed} left={left} props={resolved} />
  );
  return (
    <Section
      style={{ backgroundColor: resolved.pageBackgroundColor }}
      width="100%"
    >
      <Fragment>
        <Row>
          <Column>&zwj;</Column>
          <Column
            style={{
              backgroundColor: resolved.backgroundColor,
              maxWidth: "100%",
              width: "600px",
            }}
          >
            <Section width="100%">
              <Fragment>
                <Row>
                  <Column
                    className="cta-strip-outer-content"
                    style={{
                      paddingLeft: left ? 0 : "24px",
                      paddingRight: left ? "24px" : 0,
                    }}
                  >
                    <Section>
                      <Fragment>
                        <Row>
                          {left ? stripCell : contentCell}
                          <Column
                            className="cta-strip-stack cta-strip-gap"
                            style={{ width: "44px" }}
                          >
                            &zwj;
                          </Column>
                          {left ? contentCell : stripCell}
                        </Row>
                      </Fragment>
                    </Section>
                  </Column>
                </Row>
              </Fragment>
            </Section>
          </Column>
          <Column>&zwj;</Column>
        </Row>
      </Fragment>
    </Section>
  );
};

const Cta_CTAWithImageStrip = ({
  pageBackgroundColor = "#f1f5f9",
  theme = defaultTheme,
  variant = "boxed-right",
  ...props
}: Cta_CTAWithImageStripProps) => (
  <Html>
    <EmailHead>
      <DefaultFonts />
      <style dangerouslySetInnerHTML={{ __html: Cta_responsiveStyles }} />
    </EmailHead>
    <Preview>{props.heading ?? Cta_defaultSectionStyles.heading}</Preview>
    <EmailTailwind theme={theme}>
      <Body
        style={{
          backgroundColor: pageBackgroundColor,
        }}
        className="font-sans m-0"
      >
        <Container className="mx-auto max-w-[600px] w-[600px]">
          <Cta_CTAWithImageStripSection
            {...props}
            pageBackgroundColor={pageBackgroundColor}
            variant={variant}
          />
        </Container>
      </Body>
    </EmailTailwind>
  </Html>
);

Cta_CTAWithImageStrip.PreviewProps = {
  theme: defaultTheme,
  variant: "boxed-right",
} satisfies Cta_CTAWithImageStripProps;

const __Cta = Cta_CTAWithImageStrip;

export interface ImageStripCallToActionProps {
  theme?: Parameters<typeof __Cta>[0]["theme"];
  heading?: string;
  description?: string;
  action?: {
    href: string;
    label: string;
  };
  images?: {
    src: string;
    alt?: string;
  }[];
  placement?: "left" | "right";
  width?: "boxed" | "full";
}

const imageStripItem = (
  image:
    | {
        src: string;
        alt?: string;
      }
    | undefined
) => ({
  alt: image?.alt,
  src: image?.src,
});

export const ImageStripCallToAction = ({
  theme,
  heading,
  description,
  action,
  images,
  placement = "right",
  width = "boxed",
}: ImageStripCallToActionProps) => {
  const { href: ctaHref, label: ctaLabel } = action ?? {};
  const [first, second, third, fourth, fifth] = images ?? [];
  const image1 = imageStripItem(first);
  const image2 = imageStripItem(second);
  const image3 = imageStripItem(third);
  const image4 = imageStripItem(fourth);
  const image5 = imageStripItem(fifth);
  return (
    <__Cta
      ctaHref={ctaHref}
      ctaLabel={ctaLabel}
      heading={heading}
      imageAlt1={image1.alt}
      imageAlt2={image2.alt}
      imageAlt3={image3.alt}
      imageAlt4={image4.alt}
      imageAlt5={image5.alt}
      imageSrc1={image1.src}
      imageSrc2={image2.src}
      imageSrc3={image3.src}
      imageSrc4={image4.src}
      imageSrc5={image5.src}
      subtext={description}
      theme={theme}
      variant={`${width}-${placement}`}
    />
  );
};

ImageStripCallToAction.PreviewProps = {
  placement: "right",
  width: "boxed",
} satisfies ImageStripCallToActionProps;

const ASSET_ORIGIN = "https://www.emailcn.run";
const ICONS8_ORIGIN = "https://img.icons8.com";
const UNSPLASH_ORIGIN = "https://images.unsplash.com";

const portraitIds = [
  "photo-1500648767791-00dcc994a43e",
  "photo-1507003211169-0a1dd7228f2d",
  "photo-1494790108377-be9c29b29330",
  "photo-1438761681033-6461ffad8d80",
  "photo-1534528741775-53994a69daeb",
  "photo-1506794778202-cad84cf45f1c",
] as const;

const productIds = [
  "photo-1521572163474-6864f9cf17ab",
  "photo-1503341504253-dff4815485f1",
  "photo-1576566588028-4147f3842f27",
  "photo-1562157873-818bc0726f68",
] as const;

const socialIconSlugs = {
  discord: "discord-logo",
  facebook: "facebook-new",
  github: "github",
  instagram: "instagram-new",
  linkedin: "linkedin",
  slack: "slack-new",
  x: "twitterx--v1",
  youtube: "youtube-play",
} as const;

const brandIconSlugs = [
  [/(?:btc|bitcoin)/i, "bitcoin--v1"],
  [/(?:eth|ethereum)/i, "ethereum"],
  [/visa/i, "visa"],
  [/mastercard/i, "mastercard-logo"],
  [/apple-pay/i, "apple-pay"],
  [/google-pay/i, "google-pay"],
  [/klarna/i, "klarna"],
  [/stripe/i, "stripe"],
  [/fedex/i, "fedex"],
  [/north-face/i, "the-north-face"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/teams\/member-\d+-lg/i.test(path)) {
    return [800, 560] as const;
  }
  if (/teams\/member-\d+/i.test(path)) {
    return [600, 600] as const;
  }
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

const getIndexedAsset = (path: string, assets: readonly string[]) => {
  const explicitIndex = path.match(
    /(?:member|avatar|product-list|shopping-cart)-(\d+)/i
  )?.[1];
  const index = explicitIndex
    ? Number.parseInt(explicitIndex, 10) - 1
    : hashString(path);

  return assets[((index % assets.length) + assets.length) % assets.length];
};

const getUnsplashAsset = (id: string, width: number, height: number) =>
  `${UNSPLASH_ORIGIN}/${id}?auto=format&fit=crop&w=${width}&h=${height}&q=80`;

const getIcons8Asset = (
  slug: string,
  {
    color,
    style = "ios-filled",
  }: {
    color?: string;
    style?: "color" | "ios" | "ios-filled";
  } = {}
) =>
  color
    ? `${ICONS8_ORIGIN}/${style}/50/${color}/${slug}.png`
    : `${ICONS8_ORIGIN}/${style}/50/${slug}.png`;

const getStoreBadgeAsset = (path: string) => {
  if (/badge-app-store/i.test(path)) {
    return "https://developer.apple.com/assets/elements/badges/download-on-the-app-store.svg";
  }
  if (/badge-google-play/i.test(path)) {
    return "https://play.google.com/intl/en_us/badges/static/images/badges/en_badge_web_generic.png";
  }
};

const getSocialIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  for (const [name, slug] of Object.entries(socialIconSlugs)) {
    if (new RegExp(`(?:^|[-/])${name}(?:[-.]|$)`, "i").test(path)) {
      return getIcons8Asset(slug, { color: foreground });
    }
  }
};

const getUtilityIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  if (/star-half/i.test(path)) {
    return getIcons8Asset("star-half-empty", { color: "374151" });
  }
  if (/star-solid/i.test(path)) {
    return getIcons8Asset("star--v1", { color: "374151" });
  }
  if (/edit/i.test(path)) {
    return getIcons8Asset("edit--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/arrow-right/i.test(path)) {
    return getIcons8Asset("long-arrow-right--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/chevron-right/i.test(path)) {
    return getIcons8Asset("chevron-right", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/check/i.test(path)) {
    return getIcons8Asset("checkmark--v1", { color: foreground });
  }
};

const getBrandIconAsset = (path: string) => {
  const match = brandIconSlugs.find(([pattern]) => pattern.test(path));

  return match
    ? getIcons8Asset(match[1], {
        style: "color",
      })
    : undefined;
};

const getWordmarkAsset = (path: string) => {
  const isLight = /light/i.test(path);
  const background = isLight ? "030712" : "FFFFFF";
  const foreground = isLight ? "FFFFFF" : "111827";

  return `https://placehold.co/320x96/${background}/${foreground}.png?text=EMAILCN`;
};

const getIconAsset = (path: string) =>
  getStoreBadgeAsset(path) ??
  getSocialIconAsset(path) ??
  getUtilityIconAsset(path) ??
  getBrandIconAsset(path);

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const iconAsset = getIconAsset(normalizedPath);
  if (iconAsset) {
    return iconAsset;
  }

  const seed = getSeed(normalizedPath);
  const [width, height] = getDimensions(normalizedPath);

  if (/teams\/hero/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1521737711867-e3b97375f902", width, height);
  }

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, portraitIds),
      width,
      height
    );
  }

  if (/products\/shoe/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1542291026-7eec264c27ff", width, height);
  }

  if (/products\/phone/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1511707171634-5f897ff02aa9", width, height);
  }

  if (
    /(?:product-detail|product-lists|products\/product|shopping-cart)/i.test(
      normalizedPath
    )
  ) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, productIds),
      width,
      height
    );
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (/(?:emailcn|maizzle|logo|insignia)/i.test(normalizedPath)) {
    return getWordmarkAsset(normalizedPath);
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
